import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·21","description":"易小帖 - 卷二·21","frontmatter":{"title":"卷二·21","description":"易小帖 - 卷二·21"},"headers":[],"relativePath":"zh/classics/yixiaotie/061.md","filePath":"zh/classics/yixiaotie/061.md"}'),o={name:"zh/classics/yixiaotie/061.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·21",tabindex:"-1"},[r("卷二·21 "),e("a",{class:"header-anchor",href:"#卷二·21","aria-label":"Permalink to “卷二·21”"},"​")],-1),e("p",null,"子夏傳易，無考史志。子夏傳詩，《文選》有《子夏詩序》，或雲，詩小序亦子夏作。又子夏有《儀禮喪服》一篇，馬融諸儒曾為訓說，《風俗通》雲：穀梁赤子夏門人故舊，稱詩禮春秋皆子夏所傳述者，然並不及易。即後漢徐防上書有雲：詩書禮樂定自孔子，發明章句始於子夏。則詩禮春秋而外並書，亦並歸子夏，然亦無易名。《漢‧藝文志》易十三家，無子夏撰述，惟隋唐志有《子夏傳》二捲，不知所始。或謂：係漢時杜子夏作，以子夏名同見誤。其說見孫坦《周易析藴》，然亦無實據。嘗考陸德明《釋文》及李鼎祚《易解》亦偶引及，則在唐時已信行其書。然陳氏有雲：《釋文》、《易解》所引者，反為今《子夏傳》本所無有，又在隋唐志止雲二捲，上捲已殘闕，今所傳本有十一捲，又孫坦雲或取左氏傳證之，晚又得十八占，稱夫子曰縣官，今亦無左傳與縣官之稱。則不惟非子夏傳，亦並非隋唐所傳本矣。若晁以道謂：舊《子夏易傳》二捲，唐劉子玄已知其偽，然其書不傳，今號為《子夏傳》者，《崇文總目》知其為偽，而不知其所作之人，乃獨知為此唐時張弧所作，不知何所據而雲。然按弧為唐試大理評事，《館閣書目》曾載弧所著書，然亦無言作偽《子夏傳》者。予《仲氏易》中亦偶引傳文，並經文互異字，總見陸氏《釋文》及李氏《易解》本。若今所傳本，則向無其書，今適為崑山徐氏所雕刻，亦急閱一過，然並不引及。總之，偽書無可道耳。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
